    mediaForm?.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();const form=event.target,fields=Object.fromEntries(new FormData(form)),selected=[...selectedFiles];if(!selected.length)return toast('Select at least one property photo');if(selectedIssues.length)return toast('Remove the highlighted duplicate or invalid photo before uploading');if(selected.length>10)return toast('Select no more than 10 photos in one batch');const totalBytes=selected.reduce((sum,file)=>sum+file.size,0);if(totalBytes>20*1024*1024)return toast('The selected batch exceeds 20 MB');for(const file of selected){const validation=await validatePropertyMediaFile(file);if(validation)return toast(`${file.name}: ${validation}`,8000);}const prefix=fields.title.trim(),start=photoMedia.length;try{const files=await Promise.all(selected.map(async(file,index)=>({fileName:file.name,mediaType:file.type,base64:await fileAsBase64(file),title:prefix?(selected.length===1?prefix:`${prefix} ${index+1}`):file.name.replace(/\.[^.]+$/,''),caption:fields.caption.trim()||null,displayOrder:start+index}))),result=await api(`/crm/listings/${listing.id}/media/batch`,{method:'POST',body:{mediaKind:'image',source:fields.source,rightsBasis:fields.rightsBasis,rightsExpiresAt:fields.rightsExpiresAt,usageRightsConfirmed:form.elements.usageRightsConfirmed.checked,files}});toast(result.reviewer?.automaticApproval?(result.approvalPolicy?.managerApprovalRequired===false?`${result.uploadedCount} photos uploaded and approved under the maintained Administrator policy`:`${result.uploadedCount} photos uploaded and approved automatically because no responsible manager is maintained`):`${result.uploadedCount} photos sent to ${result.reviewer?.managerName||'the responsible manager'} for one approval review`);await refresh();}catch(error){toast(`Photo batch not uploaded: ${error.message}`,7000);}});
