async function openAssignmentQueue() {
  let leads,staff;try{[{leads},{staff}]=await Promise.all([api('/crm/assignment-queue'),api('/crm/staff')]);}catch(err){return toast(err.message);}const leader=ME.role==='admin'||['manager','director'].includes(ME.jobRole);
  const o=overlay(`<div class="modal lead-modal"><button class="close-x">×</button><h2>${ME.role==='admin'||ME.jobRole==='director'?'Company Unassigned / Pending Assignment Queue':'Pending Assignment Queue'}</h2><p class="tool-note">New leads wait unassigned for an Administrator, team lead or Director. SLA-breached unattended leads return to their routed team queue and may then be self-claimed by an eligible team agent.</p><div class="pipeline-table-wrap"><table><tr><th>Customer / opportunity</th><th>Routing reason</th><th>Current team</th><th>Status / cycle</th><th>SLA deadline</th><th>Waiting</th><th>Action</th></tr>${leads.map(l=>`<tr><td>${esc(l.contactName)}<small>${esc(l.title)}</small></td><td>${esc(l.routingReason||l.businessType||'Unmatched fallback')}</td><td>${esc(l.teamName||'Company Unassigned Queue')}</td><td>${esc(l.assignmentStatus.replace('_',' '))}<small>Cycle ${l.queueCycleNo}</small></td><td>${fmtDate(l.slaDeadline)}</td><td>${Math.floor(Number(l.queueWaitSeconds||0)/60)} minutes</td><td>${leader?`<select data-queue-agent="${l.id}"><option value="">Select eligible agent</option>${staff.filter(s=>s.jobRole==='sales_agent'&&(!l.assignedTeamId||s.teamId===l.assignedTeamId)).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select> <button class="btn btn-primary btn-sm" data-assign-queue="${l.id}" data-team="${l.assignedTeamId||''}">Assign</button>`:l.assignmentStatus==='reassignment_due'&&l.assignedTeamId===ME.teamId?`<button class="btn btn-primary btn-sm" data-claim="${l.id}">Claim for myself</button>`:'Administrator, team lead or Director assignment required'}</td></tr>`).join('')}</table>${leads.length?'':'<div class="empty">The assignment queue is clear.</div>'}</div></div>`);
  o.querySelectorAll('[data-claim]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/crm/assignment-queue/${b.dataset.claim}/claim`,{method:'POST'});toast('Lead claimed; accept the assignment within SLA');o.remove();openAssignmentQueue();loadCRMLeads();}catch(err){toast(err.message);}}));o.querySelectorAll('[data-assign-queue]').forEach(b=>b.addEventListener('click',async()=>{const agentId=o.querySelector(`[data-queue-agent="${b.dataset.assignQueue}"]`).value;if(!agentId)return toast('Select an eligible agent');try{await api(`/crm/assignment-queue/${b.dataset.assignQueue}/assign`,{method:'POST',body:{agentId,teamId:b.dataset.team||staff.find(x=>x.id===agentId)?.teamId}});toast('Lead assigned with a new SLA cycle');o.remove();openAssignmentQueue();loadCRMLeads();}catch(err){toast(err.message);}}));
}

