let adminActiveSection='actions';
function setupAdminWorkspace(){
  const view=$('#view'),sections=Array.from(view.children).filter(x=>x.classList.contains('admin-section'));
  const definitions=[['actions','My action requests'],['organization','Company profile'],['controlled_values','Controlled values'],['sla','Business hours & SLA'],['areas','Area maintenance'],['listing_mappings','Provider listing mappings'],['routing','Lead routing & queues'],['qualification','Lead qualification'],['fees','Regulatory & fee rules'],['proposals','Proposal designer'],['documents','Document templates'],['targets','Dashboard targets'],['teams','CRM teams'],['media_policy','Property media policy'],['users','User management'],['users','User records'],['operations','Operations & audit']];
  const workspace=document.createElement('div');workspace.className='admin-workspace';workspace.innerHTML='<aside class="admin-maintenance-nav"><h2>Administration</h2><p>Select one maintenance area.</p><nav aria-label="Administration maintenance"></nav></aside><section class="admin-maintenance-content"></section>';
  const nav=workspace.querySelector('nav'),content=workspace.querySelector('.admin-maintenance-content'),groups=new Map();
  sections.forEach((section,index)=>{const [key,label]=definitions[index]||[`section_${index}`,section.querySelector('h2')?.textContent||`Section ${index+1}`];section.dataset.adminSection=key;section.dataset.adminLabel=label;content.append(section);if(!groups.has(key))groups.set(key,label);});
  for(const [key,label] of groups){const button=document.createElement('button');button.type='button';button.dataset.adminTarget=key;button.textContent=label;button.addEventListener('click',()=>show(key));nav.append(button);}
  const show=key=>{adminActiveSection=groups.has(key)?key:groups.keys().next().value;sections.forEach(x=>x.classList.toggle('admin-section-active',x.dataset.adminSection===adminActiveSection));nav.querySelectorAll('button').forEach(x=>{const active=x.dataset.adminTarget===adminActiveSection;x.classList.toggle('active',active);x.setAttribute('aria-current',active?'page':'false');});};
  view.append(workspace);show(adminActiveSection);
}
