function fillOrganizationForm(o={}){const form=$('#organization-form');form.reset();form.elements.id.value=o.status==='draft'?o.id||'':'';for(const key of organizationFields){const el=form.elements[key];if(!el)continue;if(el.tagName==='SELECT'&&o[key]&&!Array.from(el.options).some(x=>x.value===o[key]))el.add(new Option(o[key],o[key]));el.value=o[key]||({defaultCurrency:'AED',timezone:'Asia/Dubai',locale:'en-AE'}[key]||'');}$('#organization-save').textContent=o.status==='draft'?`Save draft v${o.version}`:'Create draft version';}
function organizationFeedback(message,kind='info'){let box=$('#organization-feedback');if(!box){box=document.createElement('p');box.id='organization-feedback';box.setAttribute('aria-live','polite');$('#organization-form').insertAdjacentElement('afterend',box);}box.className=`tool-note ${kind}`;box.textContent=message;}
function resetOrganizationForm(notify=false){const active=organizationVersions.find(x=>x.status==='active'),button=$('#organization-reset');button.textContent='Copy active profile into form';button.disabled=!active;button.title=active?'Copy the approved active profile as the starting point for a new draft':'No active profile exists yet';if(!active){if(notify)organizationFeedback('No active profile exists to copy. Complete the form and select Create draft version.','warning');return false;}if(notify&&!confirm('Replace the current form entries with the active company profile?'))return false;fillOrganizationForm(active);if(notify)organizationFeedback(`Active profile v${active.version} copied into the form. Review it and select Create draft version to save a new draft.`,'success');return true;}
function organizationComparison(current){const prior=organizationVersions.find(x=>x.version<current.version),labels={legalName:'Legal company name',displayName:'Customer-facing name',tradeLicenseNumber:'Trade licence number',registrationAuthority:'Licensing authority',registeredAddress:'Registered office address',primaryPhone:'Company phone',primaryEmail:'Company email',websiteUrl:'Company website',defaultCurrency:'Default proposal currency',timezone:'Business timezone',locale:'Date and number format',brandVersion:'Approved brand version',proposalFooter:'Proposal page footer',defaultDisclaimer:'Default proposal disclaimer',logoFileHash:'Approved logo'};const changed=Object.keys(labels).filter(k=>(prior?.[k]||'')!==(current[k]||''));const rows=changed.map(k=>`<tr><td>${esc(labels[k])}</td><td>${esc(prior?.[k]||'—')}</td><td>${esc(current[k]||'—')}</td></tr>`).join('');overlay(`<div class="modal"><button class="close-x">×</button><h2>Company profile v${current.version} comparison</h2><p class="tool-note">Compared with ${prior?`version ${prior.version}`:'no earlier version'}.</p><table><tr><th>Setting</th><th>Earlier</th><th>Version ${current.version}</th></tr>${rows||'<tr><td colspan="3">No differences</td></tr>'}</table></div>`);}
async function loadOrganization(){
  try{({versions:organizationVersions}=await api('/admin/organization-settings'));const active=organizationVersions.find(x=>x.status==='active');if(!$('#organization-form').elements.id.value)resetOrganizationForm();
    $('#organization-version').innerHTML=`<p class="tool-note">${active?`Active company profile v${active.version}, effective ${fmtDate(active.effectiveFrom)}. New proposals snapshot this exact profile and brand asset.`:'No active profile. Create, approve and activate a draft before proposals can be generated.'}</p><p class="tool-note">Compare changes shows what differs from the immediately preceding version before approval. Unused drafts may be deleted; approved, active and historical versions are retained.</p><table><tr><th>Version</th><th>Company / brand</th><th>Regional defaults</th><th>Approval / effective dates</th><th>Status</th><th>Actions</th></tr>${organizationVersions.map(o=>`<tr><td>v${o.version}</td><td><b>${esc(o.displayName)}</b><small>${esc(o.legalName)} · brand ${esc(o.brandVersion)}</small>${o.logo?`<small><a href="${o.logo.downloadUrl}" target="_blank">${esc(o.logo.fileName)}</a> · ${esc(o.logo.fileHash.slice(0,12))}…</small>`:'<small>No approved logo attached</small>'}</td><td>${esc(o.defaultCurrency)} · ${esc(o.timezone)}<small>${esc(o.locale)}</small></td><td>${o.approvedAt?`Approved ${fmtDate(o.approvedAt)}<small>${esc(o.approvalReason||'')}</small>`:'Not approved'}${o.status==='active'?`<small>Active from ${fmtDate(o.effectiveFrom)}</small>`:''}</td><td>${esc(o.status)}</td><td>${o.status==='draft'?`<button class="btn btn-sm" data-edit-org="${o.id}">Edit</button> <button class="btn btn-sm" data-approve-org="${o.id}">Approve</button> <button class="btn btn-sm" data-delete-org="${o.id}">Delete unused draft</button>`:''}${o.status==='approved'?`<button class="btn btn-primary btn-sm" data-activate-org="${o.id}">Activate</button> <button class="btn btn-sm" data-retire-org="${o.id}">Retire</button>`:''} <button class="btn btn-sm" data-compare-org="${o.id}">Compare changes</button></td></tr>`).join('')||'<tr><td colspan="6">No company profile versions yet.</td></tr>'}</table>`;
    document.querySelectorAll('[data-edit-org]').forEach(b=>b.addEventListener('click',()=>fillOrganizationForm(organizationVersions.find(x=>x.id===b.dataset.editOrg))));document.querySelectorAll('[data-compare-org]').forEach(b=>b.addEventListener('click',()=>organizationComparison(organizationVersions.find(x=>x.id===b.dataset.compareOrg))));document.querySelectorAll('[data-approve-org]').forEach(b=>b.addEventListener('click',async()=>{const reason=prompt('Approval reason (required)');if(!reason)return;try{await api(`/admin/organization-settings/${b.dataset.approveOrg}/approve`,{method:'POST',body:{reason}});toast('Company profile approved; activate it when ready');loadOrganization();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-activate-org]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/admin/organization-settings/${b.dataset.activateOrg}/activate`,{method:'POST'});toast('Approved company profile activated');loadOrganization();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-retire-org]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Retire this approved profile version?'))return;try{await api(`/admin/organization-settings/${b.dataset.retireOrg}/retire`,{method:'POST'});loadOrganization();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-delete-org]').forEach(b=>b.addEventListener('click',async()=>{const version=organizationVersions.find(x=>x.id===b.dataset.deleteOrg);if(!confirm(`Permanently delete unused draft v${version.version}? Approved, active and historical versions cannot be deleted.`))return;const reason=prompt('Deletion reason (required)','Duplicate created during failed logo upload');if(!reason)return;try{await api(`/admin/organization-settings/${b.dataset.deleteOrg}`,{method:'DELETE',body:{reason}});toast(`Unused draft v${version.version} deleted`);loadOrganization();}catch(err){toast(err.message);}}));
  }catch(err){$('#organization-version').textContent=err.message;}
}

async function saveOrganization(e){e.preventDefault();const form=e.target,body=Object.fromEntries(new FormData(form)),id=body.id,rawFile=form.elements.logoFile.files[0],file=rawFile?.name?rawFile:null;delete body.id;delete body.logoFile;if(file&&file.size<1){organizationFeedback('Draft not saved: the selected logo file is empty. Choose a PNG, JPG or WEBP file between 1 byte and 2 MB, or leave the logo unselected.','error');return;}if(file&&file.size>2097152){organizationFeedback('Draft not saved: the selected logo is larger than 2 MB. Choose a smaller PNG, JPG or WEBP file, or leave the logo unselected.','error');return;}if(file&&!['image/jpeg','image/png','image/webp'].includes(file.type)){organizationFeedback('Draft not saved: choose a PNG, JPG or WEBP logo file, or leave the logo unselected.','error');return;}let logoBase64=null;if(file){try{logoBase64=await fileAsBase64(file);if(!logoBase64)throw new Error('The selected logo could not be read');}catch(err){organizationFeedback(`Draft not saved: ${err.message}. Choose another logo file or leave the logo unselected.`,'error');return;}}let saved;try{saved=await api(id?`/admin/organization-settings/${id}`:'/admin/organization-settings',{method:id?'PATCH':'POST',body});}catch(err){toast(err.message);organizationFeedback(`Draft not saved: ${err.message}`,'error');return;}const message=id?`Company profile draft v${saved.version} updated`:`Company profile draft v${saved.version} created`;if(file){try{await api(`/admin/organization-settings/${saved.id}/logo`,{method:'POST',body:{fileName:file.name,mediaType:file.type,base64:logoBase64}});}catch(err){toast('Company profile saved; logo not attached');fillOrganizationForm(saved);await loadOrganization();organizationFeedback(`${message}, but the selected logo was not attached: ${err.message}. The form remains linked to draft v${saved.version}; choose another logo and save again to update this same version.`,'warning');return;}}toast(message);fillOrganizationForm({});await loadOrganization();organizationFeedback(`${message}. It is listed below and remains inactive until approved and activated.`,'success');}

async function createValueSet(e){e.preventDefault();try{await api('/admin/value-sets',{method:'POST',body:Object.fromEntries(new FormData(e.target))});e.target.reset();toast('Value set created');loadValueSets();}catch(err){toast(err.message);}}

async function loadValueSets(){
  try{const{sets}=await api('/admin/value-sets');$('#value-set-table').innerHTML=sets.length?`<table class="controlled-values-table"><tr><th>Value set</th><th>Class</th><th>Definition</th><th>Status / usage</th><th>Definition actions</th><th>Set actions</th></tr>${sets.map(s=>(s.definitions?.length?s.definitions:[null]).map((v,i)=>`<tr>${i===0?`<td rowspan="${Math.max(1,s.definitions.length)}"><b>${esc(s.name)}</b><small class="mono">${esc(s.stableCode)}</small><small>${esc(s.status)}</small></td><td rowspan="${Math.max(1,s.definitions.length)}">${esc(s.configurationClass)}</td>`:''}<td>${v?`<b>${esc(v.displayLabelEn)}</b><small class="mono">${esc(v.stableCode)}</small>`:'No definitions'}</td><td>${v?`${esc(v.definitionStatus)} · used ${v.usageCount||0} times`:'—'}</td><td>${v?`${v.definitionStatus==='draft'?`<button class="btn btn-sm" data-edit-definition="${v.id}">Edit</button> <button class="btn btn-sm" data-delete-definition="${v.id}">Delete unused draft</button> <button class="btn btn-sm" data-activate-definition="${v.id}">Activate</button>`:`<button class="btn btn-sm" data-retire-definition="${v.id}">Retire / replace</button>`}`:'—'}</td>${i===0?`<td rowspan="${Math.max(1,s.definitions.length)}"><button class="btn btn-sm" data-add-definition="${s.id}">Add definition</button> <button class="btn btn-sm" data-add-consumer="${s.id}">Connect consumer</button>${s.status==='draft'?` <button class="btn btn-sm" data-activate-set="${s.id}">Activate set</button> <button class="btn btn-sm" data-delete-set="${s.id}">Delete empty draft</button>`:''}<small>${(s.consumers||[]).map(c=>`${esc(c.moduleName)} · ${esc(c.businessLabel)}`).join('<br>')||'No consumers connected'}</small></td>`:''}</tr>`).join('')).join('')}</table>`:'<div class="empty">No controlled value sets yet.</div>';
    document.querySelectorAll('[data-add-definition]').forEach(b=>b.addEventListener('click',()=>openValueDefinition(b.dataset.addDefinition)));document.querySelectorAll('[data-edit-definition]').forEach(b=>b.addEventListener('click',async()=>{const stableCode=prompt('Correct stable code (allowed only while unused draft)'),displayLabelEn=prompt('English business label');if(!stableCode||!displayLabelEn)return;try{await api(`/admin/value-definitions/${b.dataset.editDefinition}`,{method:'PATCH',body:{stableCode,displayLabelEn}});loadValueSets();}catch(err){toast(err.message);}}));
    document.querySelectorAll('[data-activate-definition]').forEach(b=>b.addEventListener('click',async()=>{const changeReason=prompt('Approval/change reason');if(!changeReason)return;const impactReview=prompt('Impact review, transition/report mapping, migration and test assessment');if(!impactReview)return;try{await api(`/admin/value-definitions/${b.dataset.activateDefinition}`,{method:'PATCH',body:{definitionStatus:'active',changeReason,impactReview,effectiveFrom:new Date().toISOString()}});loadValueSets();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-delete-definition]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete this unused draft definition?'))return;try{await api(`/admin/value-definitions/${b.dataset.deleteDefinition}`,{method:'DELETE'});loadValueSets();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-retire-definition]').forEach(b=>b.addEventListener('click',async()=>{const changeReason=prompt('Retirement reason');if(!changeReason)return;const impactReview=prompt('Impact and replacement review');if(!impactReview)return;try{await api(`/admin/value-definitions/${b.dataset.retireDefinition}`,{method:'PATCH',body:{definitionStatus:'retired',changeReason,impactReview,effectiveTo:new Date(Date.now()+60000).toISOString()}});loadValueSets();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-activate-set]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/admin/value-sets/${b.dataset.activateSet}`,{method:'PATCH',body:{status:'active'}});loadValueSets();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-delete-set]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete this empty draft set?'))return;try{await api(`/admin/value-sets/${b.dataset.deleteSet}`,{method:'DELETE'});loadValueSets();}catch(err){toast(err.message);}}));document.querySelectorAll('[data-add-consumer]').forEach(b=>b.addEventListener('click',async()=>{const consumerCode=prompt('Consumer stable code, e.g. lead.loss_reason')?.replace(/\./g,'_'),businessLabel=prompt('Business field label'),moduleName=prompt('Module name'),fieldName=prompt('Field name');if(!consumerCode||!businessLabel||!moduleName||!fieldName)return;try{await api(`/admin/value-sets/${b.dataset.addConsumer}/consumers`,{method:'POST',body:{consumerCode,businessLabel,moduleName,fieldName}});loadValueSets();}catch(err){toast(err.message);}}));
  }catch(err){$('#value-set-table').textContent=err.message;}
}

function openValueDefinition(setId){const o=overlay(`<div class="modal"><button class="close-x">×</button><h2>Add controlled value draft</h2><form id="definition-form"><div class="form-grid"><div><label>Stable code *</label><input name="stableCode" required pattern="[a-z][a-z0-9_]*" placeholder="loss_reason"><small>Lowercase snake_case only</small></div><div><label>English label *</label><input name="displayLabelEn" required></div><div><label>Arabic label</label><input name="displayLabelAr"></div><div><label>Display order</label><input name="displayOrder" type="number" value="0"></div><div><label><input name="isDefault" type="checkbox"> Default</label></div></div><div class="modal-actions"><button class="btn btn-primary">Create draft</button></div></form></div>`);$('#definition-form',o).addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.isDefault=Boolean(f.isDefault);try{await api(`/admin/value-sets/${setId}/definitions`,{method:'POST',body:f});toast('Controlled value draft created');o.remove();loadValueSets();}catch(err){toast(err.message);}});}

async function createTeam() {
  try {
    await api('/crm/teams', { method:'POST', body:{ name:$('#team-name').value.trim(), leadResponseHours:+$('#team-sla').value } });
    $('#team-name').value=''; toast('Team created'); loadTeams(); loadBrokers();
  } catch (err) { toast(err.message); }
}

async function loadTeams() {
  try {
    const [{ teams },{ staff }] = await Promise.all([api('/crm/teams'),api('/crm/staff')]);
    $('#team-table').innerHTML = teams.length ? `<table><tr><th>Team</th><th>Manager</th><th>Members</th><th>Response SLA</th><th></th></tr>${teams.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td><select data-team-manager="${t.id}" style="width:170px"><option value="">Unassigned</option>${staff.filter(s=>s.jobRole==='manager'||s.id===t.managerId).map(s=>`<option value="${s.id}" ${t.managerId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></td><td>${t.memberCount}</td><td><input data-team-sla="${t.id}" type="number" min="1" max="168" value="${t.leadResponseHours}" style="width:80px"></td><td><button class="btn btn-danger btn-sm" data-team-deactivate="${t.id}">Deactivate</button></td></tr>`).join('')}</table>` : '<div class="empty">No teams yet. Create the first team before assigning leads.</div>';
    const save=async(id,body)=>{try{await api('/crm/teams/'+id,{method:'PATCH',body});toast('Team updated');loadTeams();}catch(err){toast(err.message);}};
    document.querySelectorAll('[data-team-manager]').forEach(s=>s.addEventListener('change',()=>save(s.dataset.teamManager,{managerId:s.value||null})));
    document.querySelectorAll('[data-team-sla]').forEach(i=>i.addEventListener('change',()=>save(i.dataset.teamSla,{leadResponseHours:+i.value})));
    document.querySelectorAll('[data-team-deactivate]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Deactivate this team? Existing history is retained.'))save(b.dataset.teamDeactivate,{active:false});}));
  } catch (err) { $('#team-table').textContent=err.message; }
}

async function createInvite() {
  try {
    const inv = await api('/admin/invitations', { method: 'POST', body: {
      issuedToEmail: $('#inv-email').value.trim() || null,
      role: $('#inv-role').value,
      jobRole: $('#inv-job-role').value,
      teamId: $('#inv-team').value||null,
      expiresAt: $('#inv-exp').value || null
    }});
    toast('Invitation created: ' + inv.code);
    loadInvites();
  } catch (err) { toast(err.message); }
}

async function addUser(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),roles=f.userClassification==='internal_user'?[{jobRole:f.jobRole,teamId:f.teamId||null,isPrimary:true,changeReason:'Initial approved primary role'}]:[];try{const result=await api('/admin/users',{method:'POST',body:{name:f.name,email:f.email,userClassification:f.userClassification,roleAssignments:roles}});toast(result.activationCode?`Pending user added. Activation code: ${result.activationCode}`:'External interface identity added without login access');e.target.reset();loadBrokers();loadInvites();}catch(err){toast(err.message);}}

async function loadInvites() {
  try {
    const { invitations } = await api('/admin/invitations');
    $('#inv-table').innerHTML = `<table><tr><th>Code</th><th>Access / job role</th><th>Scoped to</th><th>Uses</th><th>Expires</th><th>Status</th><th></th></tr>
    ${invitations.map(i => `<tr>
      <td class="mono">${esc(i.code)}</td><td>${esc(ROLES[i.role])}${i.jobRole?' · '+esc(JOB_ROLES[i.jobRole]||i.jobRole):''}</td><td>${esc(i.issuedToEmail || 'Anyone')}</td>
      <td>${i.usedCount}/${i.maxUses}</td><td>${i.expiresAt ? esc(i.expiresAt.slice(0,10)) : '—'}</td>
      <td><span class="pill ${esc(i.status)}">${esc(i.status)}</span></td>
      <td>${i.status === 'active' ? `<button class="btn btn-sm btn-danger" data-revoke-inv="${i.id}">Revoke</button>` : ''}</td>
    </tr>`).join('')}</table>`;
    document.querySelectorAll('[data-revoke-inv]').forEach(b => b.addEventListener('click', async () => {
      try { await api('/admin/invitations/' + b.dataset.revokeInv, { method: 'DELETE' }); loadInvites(); } catch (e) { toast(e.message); }
    }));
  } catch (err) { $('#inv-table').textContent = err.message; }
}

async function loadBrokers() {
  try {
    const [{ brokers }, { teams }] = await Promise.all([api('/admin/brokers'), api('/crm/teams')]);
    const directors=brokers.filter(b=>b.role==='internal_broker'&&b.jobRole==='director'&&b.status==='active');
    $('#broker-table').innerHTML = `<table><tr><th>User</th><th>Classification</th><th>Effective roles</th><th>Primary role</th><th>Team / reporting line</th><th>Status</th><th>Actions</th></tr>
    ${brokers.map(b => `<tr>
      <td><b>${esc(b.name)}</b><small>${esc(b.email)}</small></td><td>${esc((b.userClassification||b.role).replaceAll('_',' '))}</td><td>${(b.roleAssignments||[]).map(r=>`${esc(JOB_ROLES[r.jobRole]||r.jobRole)}${r.isPrimary?' · Primary':''}${r.status!=='active'?` · ${esc(r.status)}`:''}`).join('<br>')||'—'}<br><button class="btn btn-sm" data-add-user-role="${b.id}">Add role</button></td>
      <td>${['admin','internal_broker'].includes(b.role)?`<select data-job-role="${b.id}" style="width:150px">${Object.entries(JOB_ROLES).map(([k,v])=>`<option value="${k}" ${b.jobRole===k?'selected':''}>${v}</option>`).join('')}</select>`:'—'}</td>
      <td>${['admin','internal_broker'].includes(b.role) ? `<select data-team="${b.id}" style="width:170px"><option value="">Unassigned</option>${teams.map(t=>`<option value="${t.id}" ${b.teamId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${b.jobRole==='manager'?`<label class="reporting-director-label">Reports to Director<select data-reports-to="${b.id}"><option value="">Not assigned</option>${directors.map(d=>`<option value="${d.id}" ${b.reportsToId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label>`:`<small>${b.reportingManagerName?`Reports to: ${esc(b.reportingManagerName)}`:b.teamId?'Reporting manager not assigned':'No team reporting line'}</small>`}${teams.filter(t=>t.managerId===b.id).length?`<small>Manages: ${teams.filter(t=>t.managerId===b.id).map(t=>esc(t.name)).join(', ')}</small>`:''}` : '—'}</td>
      <td><span class="pill ${esc(b.status)}">${esc(b.status)}</span></td>
      <td>${b.id !== ME.id ? (b.status === 'active'
        ? `<button class="btn btn-sm" data-suspend="${b.id}">Suspend</button> <button class="btn btn-sm btn-danger" data-revoke="${b.id}">Revoke access</button>`
        : b.status==='suspended'?`<button class="btn btn-sm" data-restore="${b.id}">Reactivate</button> <button class="btn btn-sm btn-danger" data-revoke="${b.id}">Revoke access</button>`:'') : ''}</td>
    </tr>`).join('')}</table>`;
    const patch = async (id, body) => { try { await api('/admin/brokers/' + id, { method: 'PATCH', body }); loadBrokers(); } catch (e) { toast(e.message); loadBrokers(); } };
    document.querySelectorAll('[data-job-role]').forEach(s => s.addEventListener('change', () => patch(s.dataset.jobRole, { jobRole: s.value })));
    document.querySelectorAll('[data-team]').forEach(s => s.addEventListener('change', () => patch(s.dataset.team, { teamId: s.value || null })));
    document.querySelectorAll('[data-reports-to]').forEach(s=>s.addEventListener('change',()=>patch(s.dataset.reportsTo,{reportsToId:s.value||null})));
    const access=async(id,action)=>{const reason=prompt(`${action} reason (required)`);if(!reason)return;try{await api(`/admin/users/${id}/access`,{method:'POST',body:{action,reason}});loadBrokers();}catch(err){toast(err.message);}};document.querySelectorAll('[data-suspend]').forEach(b=>b.addEventListener('click',()=>access(b.dataset.suspend,'suspend')));document.querySelectorAll('[data-revoke]').forEach(b=>b.addEventListener('click',()=>access(b.dataset.revoke,'revoke')));document.querySelectorAll('[data-restore]').forEach(b=>b.addEventListener('click',()=>access(b.dataset.restore,'reactivate')));document.querySelectorAll('[data-add-user-role]').forEach(b=>b.addEventListener('click',async()=>{const jobRole=prompt('Additional role code: '+Object.keys(JOB_ROLES).join(', ')),teamId=prompt('Team ID if scoped (leave blank if none)'),changeReason=prompt('Approval/change reason');if(!jobRole||!changeReason)return;try{await api(`/admin/users/${b.dataset.addUserRole}/roles`,{method:'POST',body:{jobRole,teamId:teamId||null,isPrimary:false,changeReason}});loadBrokers();}catch(err){toast(err.message);}}));
  } catch (err) { $('#broker-table').textContent = err.message; }
}

async function loadPasswordResetRequests(){
  const target=$('#password-reset-table');if(!target)return;
  try{const{requests}=await api('/admin/password-reset-requests');target.innerHTML=requests.length?`<table><tr><th>User</th><th>Requested</th><th>Status / expiry</th><th>Administrator action</th></tr>${requests.map(r=>`<tr><td><b>${esc(r.name)}</b><small>${esc(r.email)}</small></td><td>${fmtDate(r.requestedAt)}</td><td>${esc(r.status)}${r.expiresAt?`<small>Expires ${fmtDate(r.expiresAt)}</small>`:''}</td><td><button class="btn btn-primary btn-sm" data-issue-reset="${r.id}">${r.status==='issued'?'Issue replacement code':'Issue one-time code'}</button> <button class="btn btn-sm" data-cancel-reset="${r.id}">Cancel</button></td></tr>`).join('')}</table>`:'<div class="empty">No open password reset requests.</div>';
    document.querySelectorAll('[data-issue-reset]').forEach(b=>b.addEventListener('click',async()=>{try{const result=await api(`/admin/password-reset-requests/${b.dataset.issueReset}/issue`,{method:'POST'});alert(`One-time reset code (shown only now):\n\n${result.code}\n\nExpires in ${result.expiresInMinutes} minutes. Provide it through an approved private channel.`);loadPasswordResetRequests();}catch(err){toast(err.message);}}));
    document.querySelectorAll('[data-cancel-reset]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Cancel this password reset request?'))return;try{await api(`/admin/password-reset-requests/${b.dataset.cancelReset}`,{method:'DELETE'});loadPasswordResetRequests();}catch(err){toast(err.message);}}));
  }catch(err){target.textContent=err.message;}
}

async function loadAdminMyTasks(){
  const target=$('#admin-my-task-table');if(!target)return;
  try{const{tasks}=await api('/crm/tasks?mine=1&bucket=open');target.innerHTML=tasks.length?`<table><tr><th>Priority</th><th>Action required</th><th>Customer / lead</th><th>Status</th><th>Due</th><th>Actions</th></tr>${tasks.map(t=>`<tr class="${isProposalCorrectionTask(t)?'proposal-correction-row':''}"><td><span class="pill">${esc(t.priority)}</span></td><td>${taskDescription(t)}</td><td>${esc(t.contactName)}<small>${esc(t.leadTitle)}</small></td><td>${esc(t.status.replaceAll('_',' '))}</td><td>${fmtDate(t.dueAt)}</td><td class="task-workspace-actions">${taskActions(t)}</td></tr>`).join('')}</table>`:'<div class="empty">No action requests are assigned to you.</div>';
    bindTaskActions(target,tasks,loadAdminMyTasks);
  }catch(err){target.textContent=err.message;}
}

async function loadAudit() {
  try {
    const p = $('#al-type').value ? '?entityType=' + $('#al-type').value : '';
    const { entries } = await api('/admin/audit-log' + p);
    $('#audit-table').innerHTML = `<table><tr><th>When</th><th>Entity</th><th>Action</th><th>By</th><th>Details</th></tr>
    ${entries.map(e => `<tr>
      <td style="white-space:nowrap">${fmtDate(e.timestamp)}</td>
      <td>${esc(e.entityType)} <span class="mono" style="color:var(--muted)">${esc(e.entityId.slice(0, 8))}</span></td>
      <td>${esc(e.action)}</td><td>${esc(e.performedByName)}</td>
      <td>${e.details ? `<details class="json-details"><summary>view</summary><pre class="mono" style="white-space:pre-wrap;font-size:11px;color:var(--muted)">${esc(JSON.stringify(JSON.parse(e.details), null, 1))}</pre></details>` : '—'}</td>
    </tr>`).join('')}</table>`;
  } catch (err) { $('#audit-table').textContent = err.message; }
}

/* ============ BOOT ============ */
(async function boot() {
  try { ME = await api('/me'); return renderShell(); } catch {}
  try {
    const setup = await api('/auth/setup-status');
    if (setup.needsSetup) return renderSetup(setup.setupEnabled);
  } catch {}
  renderLogin();
})();

