  form.elements.proposalId.addEventListener('change',refreshTemplate);form.elements.financialScenarioId.addEventListener('change',()=>{delete form.elements.assumptions.dataset.reviewed;refreshAssumption();});form.elements.assumptions.addEventListener('input',()=>form.elements.assumptions.dataset.reviewed='1');
  propertyChecks.forEach(x=>x.addEventListener('change',()=>{const max=Number(form.elements.maxProperties.value||3);if(selectedListingIds().length>max){x.checked=false;toast(`The active template allows no more than ${max} properties`);}refreshMedia();}));
  mediaChecks.forEach(x=>x.addEventListener('change',()=>{const max=Number(form.elements.maxMedia.value||2),count=mediaChecks.filter(y=>y.checked&&y.dataset.listingId===x.dataset.listingId).length;if(count>max){x.checked=false;toast(`The active template allows no more than ${max} approved media items for this property`);}}));
