  $('#proposal-ai-draft',form).addEventListener('click',async e=>{const ids=selectedListingIds();if(!ids.length)return toast('Select at least one shortlisted property first');e.target.disabled=true;aiResult.innerHTML='<p class="tool-note">Drafting evidence-based wording for the reviewed shortlist...</p>';try{const drafts=[];for(const id of ids){const data=await api(`/crm/leads/${lead.id}/ai/match-explanation`,{method:'POST',body:{listingId:id}});drafts.push({candidate:selectedCandidate(id),suggestion:data.suggestion});}const highlights=drafts.map(x=>`${x.candidate.listing.inventoryReference||x.candidate.listing.project}: ${x.suggestion.headline}`).join('\n'),suitability=drafts.map(x=>`${x.candidate.listing.inventoryReference||x.candidate.listing.project}\n${x.suggestion.customerSummary}\nWhy it matches: ${(x.suggestion.whyItMatches||[]).join('; ')}\nTrade-offs: ${(x.suggestion.tradeOffs||[]).join('; ')}`).join('\n\n');const highlightTarget=inputBox.querySelector('[data-proposal-input*="highlight" i]')||inputBox.querySelector('[data-proposal-standard="highlights"]'),suitabilityTarget=inputBox.querySelector('[data-proposal-input="suitability"],[data-proposal-input="value_assessment"],[data-proposal-input="match_rationale"]')||inputBox.querySelector('[data-proposal-standard="suitability"]');if(highlightTarget)highlightTarget.value=highlights;if(suitabilityTarget)suitabilityTarget.value=suitability;aiResult.innerHTML='<div class="ai-suggestion-card"><b>Draft applied for review</b><p>Edit the highlights, suitability and trade-offs below. Nothing has been saved or generated yet.</p></div>';}catch(err){aiResult.innerHTML=`<div class="ai-suggestion-card"><b>AI draft not generated</b><p>${esc(err.message)}</p>${err.data?.runId?`<small>Reference: ${esc(err.data.runId)}</small>`:''}</div>`;}finally{e.target.disabled=false;}});
  $('#proposal-check-gaps',form).addEventListener('click',async e=>{const ids=selectedListingIds();e.target.disabled=true;aiResult.innerHTML='<p class="tool-note">Checking authoritative customer, requirement and inventory records...</p>';try{const data=await api(`/crm/leads/${lead.id}/ai/missing-information`,{method:'POST',body:{purpose:'proposal',listingIds:ids}}),s=data.suggestion,rows=items=>(items||[]).map(x=>{const listing=candidates.find(c=>c.listing.inventoryReference===x.sourceRecord)?.listing,source=x.sourceRecord==='requirement'?'Structured requirements':listing?`Inventory · ${listing.inventoryReference}`:x.sourceRecord,action=x.sourceRecord==='requirement'?'<button class="btn btn-sm" type="button" data-gap-requirement>Maintain requirements</button>':listing?`<button class="btn btn-sm" type="button" data-gap-listing="${listing.id}">Open inventory record</button>`:'';return`<li><b>${esc(proposalGapLabel(x.field))}</b><small>${esc(source)}</small><p>${esc(x.reason)}</p>${action}</li>`;}).join('');aiResult.innerHTML=`<div class="ai-suggestion-card"><b>${s.canProceed?'Ready after human review':'Resolve blocking information first'}</b><h4>Blocking</h4><ul>${rows(s.blocking)||'<li>None identified</li>'}</ul><h4>Recommended</h4><ul>${rows(s.recommended)||'<li>None identified</li>'}</ul></div>`;}catch(err){aiResult.innerHTML=`<div class="ai-suggestion-card"><b>Check not completed</b><p>${esc(err.message)}</p></div>`;}finally{e.target.disabled=false;}});
  aiResult.addEventListener('click',e=>{if(e.target.matches('[data-gap-requirement]')){o.remove();openLeadRequirements(lead);}if(e.target.matches('[data-gap-listing]')){o.remove();switchTab('listings');setTimeout(()=>openDetail(e.target.dataset.gapListing),0);}});
