/* ============ MODEL-DRIVEN QUALIFICATION ============ */
const qualificationOptions=text=>String(text||'').split(/[;\n]+/).map(x=>x.trim()).filter(Boolean).map(x=>{const at=x.lastIndexOf('=');return at>0?{label:x.slice(0,at).trim(),value:Number(x.slice(at+1).trim())}:null;}).filter(Boolean);
addQualificationFactor=function(f={}){const row=document.createElement('div');row.className='qualification-factor-card qualification-factor';row.innerHTML=`<div class="qualification-factor-head"><b>Qualification question</b><div><button class="btn btn-sm" data-move="up" type="button">Move up</button> <button class="btn btn-sm" data-move="down" type="button">Move down</button> <button class="btn btn-sm" data-remove type="button">Remove</button></div></div><div class="form-grid qualification-factor-grid"><div><label>Factor name *</label><input data-field="label" required placeholder="e.g. Budget readiness" value="${esc(f.label||'')}"></div><div class="span2"><label>Question shown to agent *</label><input data-field="question" required placeholder="Write one clear business question" value="${esc(f.question||f.description||'')}"></div><div class="span2"><label>Help text</label><input data-field="description" placeholder="Explain what the agent should confirm" value="${esc(f.description||'')}"></div><div><label>Stable code *</label><input data-field="code" required placeholder="stable_code" pattern="[a-z][a-z0-9_]*" value="${esc(f.code||'')}"></div><div><label>Answer format *</label><select data-field="answerType"><option value="scale">Number / scale</option><option value="yes_no">Yes / No</option><option value="single_select">Dropdown choices</option></select></div><div><label>Answer choices</label><input data-field="optionText" placeholder="Ready=10; Exploring=3" value="${esc((f.answerOptions||[]).map(x=>`${x.label}=${x.value}`).join('; '))}"></div><div><label>Answer source</label><select data-field="inputSource"><option value="agent_confirmed">Agent confirmed</option><option value="system">System field</option></select></div><div><label>Minimum score</label><input data-field="min" type="number" value="${f.min??0}"></div><div><label>Maximum score</label><input data-field="max" type="number" value="${f.max??10}"></div><div><label>Weight % *</label><input data-field="weight" type="number" min="0" max="100" required value="${f.weight??0}"></div><div><label><input data-field="required" type="checkbox" ${f.required?'checked':''}> Answer required</label></div><div><label>If unanswered</label><select data-field="missingTreatment"><option value="reject">Do not calculate</option><option value="zero">Score zero</option><option value="exclude">Exclude from score</option></select></div></div>`;for(const name of ['answerType','inputSource','missingTreatment'])row.querySelector(`[data-field="${name}"]`).value=f[name]||(name==='answerType'?'scale':name==='inputSource'?'agent_confirmed':'reject');const sync=()=>{const type=row.querySelector('[data-field="answerType"]').value,options=row.querySelector('[data-field="optionText"]');options.closest('div').hidden=type!=='single_select';options.required=type==='single_select';if(type==='yes_no'){row.querySelector('[data-field="min"]').value=0;row.querySelector('[data-field="max"]').value=1;}};row.querySelector('[data-field="answerType"]').addEventListener('change',sync);sync();row.querySelector('[data-remove]').onclick=()=>{row.remove();updateQualificationWeight();};row.querySelector('[data-move="up"]').onclick=()=>{const p=row.previousElementSibling;if(p)row.parentElement.insertBefore(row,p);};row.querySelector('[data-move="down"]').onclick=()=>{const n=row.nextElementSibling;if(n)row.parentElement.insertBefore(n,row);};row.querySelectorAll('input').forEach(x=>x.addEventListener('input',updateQualificationWeight));$('#qualification-factors').append(row);updateQualificationWeight();};
function closeQualificationForm(){const form=$('#qualification-model-form');form.classList.add('hidden');$('#qualification-new').classList.remove('hidden');}
createQualificationModel=async function(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),factors=collectRows('.qualification-factor').map(x=>{const answerOptions=qualificationOptions(x.optionText);delete x.optionText;return{...x,answerOptions};});try{const body={...f,factors,guidance:{Cold:{strategy:f.coldGuidance},Warm:{strategy:f.warmGuidance},Hot:{strategy:f.hotGuidance}},thresholds:{warmMin:Number(f.warmMin),hotMin:Number(f.hotMin)}};await api('/admin/qualification-models',{method:'POST',body});toast('Draft saved. Test it, then approve and activate it before assessing leads.');closeQualificationForm();loadQualificationModels();}catch(err){toast(err.message);}};

function qualificationQuestionControl(f){const required=f.required?'required':'';if(f.answerType==='yes_no')return `<select name="${esc(f.code)}" data-qualification-answer ${required}><option value="">Select an answer</option><option value="1">Yes</option><option value="0">No</option></select>`;if(f.answerType==='single_select')return `<select name="${esc(f.code)}" data-qualification-answer ${required}><option value="">Select an answer</option>${f.answerOptions.map(x=>`<option value="${Number(x.value)}">${esc(x.label)}</option>`).join('')}</select>`;return `<input name="${esc(f.code)}" data-qualification-answer type="number" min="${Number(f.min)}" max="${Number(f.max)}" step="any" ${required} placeholder="${Number(f.min)} to ${Number(f.max)}">`;}
async function openQualificationQuestionnaire(lead,parent){let model,canOverride,assessments;try{[{model,canOverride},{assessments}]=await Promise.all([api(`/crm/leads/${lead.id}/qualification-questionnaire`),api(`/crm/leads/${lead.id}/qualification-assessments`)]);}catch(err){return toast(err.message);}const o=overlay(`<div class="modal lead-modal"><button class="close-x">×</button><h2>Assess qualification</h2><p class="tool-note">${esc(model.name)} v${model.version} · ${esc(model.purpose)}. Answer the approved questions; Hot, Warm or Cold is calculated from maintained weights and score bands.</p><form id="qualification-questionnaire"><div class="qualification-question-list">${model.factors.map(f=>`<div class="qualification-question"><label>${esc(f.question)}${f.required?' *':''}</label>${f.description?`<small>${esc(f.description)}</small>`:''}${qualificationQuestionControl(f)}<small>Weight ${Number(f.weight)}%</small></div>`).join('')}</div>${canOverride?`<details><summary>Authorized manager override</summary><div class="admin-toolbar"><div><label>Override calculated result</label><select name="overrideTemperature"><option value="">No override</option><option>Hot</option><option>Warm</option><option>Cold</option></select></div><div><label>Mandatory override reason</label><input name="overrideReason"></div></div></details>`:''}<div class="modal-actions"><button type="button" class="btn" id="qualification-cancel">Cancel</button><button class="btn btn-primary">Calculate and save</button></div></form><div id="qualification-result"></div>${assessments.length?`<details class="qualification-history"><summary>Previous assessments (${assessments.length})</summary>${assessments.map(a=>`<div class="activity-row"><div><b>${esc(a.finalTemperature)} · score ${a.calculatedScore}</b><small>${esc(a.modelName)} v${a.modelVersion} · ${fmtDate(a.assessedAt)}</small></div></div>`).join('')}</details>`:''}</div>`);$('#qualification-cancel',o).addEventListener('click',()=>o.remove());$('#qualification-questionnaire',o).addEventListener('submit',async e=>{e.preventDefault();const inputs=Object.fromEntries(model.factors.map(f=>[f.code,e.target.elements[f.code].value])),overrideTemperature=e.target.elements.overrideTemperature?.value||'',overrideReason=e.target.elements.overrideReason?.value||'';try{const saved=await api(`/crm/leads/${lead.id}/qualification-assessments`,{method:'POST',body:{inputs,overrideTemperature,overrideReason}}),recommendation=saved.recommendation||{};$('#qualification-result',o).innerHTML=`<div class="qualification-result"><h3>${esc(saved.finalTemperature)} · score ${saved.calculatedScore}</h3><p>${esc(recommendation.strategy||'Qualification calculated from the active approved model.')}</p>${saved.contributions.map(x=>`<div><b>${esc(x.label)}</b><span>Answer ${x.value??'missing'} · weight ${x.weight}% · contribution ${Number(x.contribution||0).toFixed(2)}</span></div>`).join('')}${saved.overrideReason?`<p>Authorized override: ${esc(saved.overrideReason)}</p>`:''}</div>`;const value=$('#lead-qualification-value',parent);if(value)value.value=saved.finalTemperature;const badge=parent.querySelector('.lead-temp');if(badge){badge.textContent=saved.finalTemperature;badge.className=`lead-temp temp-${saved.finalTemperature.toLowerCase()}`;}toast('Qualification calculated and assessment history saved');loadCRMLeads();}catch(err){toast(err.message);}});}

openQualificationQuestionnaire=async function(lead,parent){
  let model,canOverride,assessments;try{[{model,canOverride},{assessments}]=await Promise.all([api(`/crm/leads/${lead.id}/qualification-questionnaire`),api(`/crm/leads/${lead.id}/qualification-assessments`)]);}catch(err){return toast(err.message);}
  const o=overlay(`<div class="modal lead-modal"><button class="close-x">×</button><h2>Assess qualification</h2><p class="tool-note">${esc(model.name)} v${model.version} · ${esc(model.purpose)}. Answer the approved questions to calculate a new assessment. A manager override is applied separately to an existing result and never asks for the answers again.</p><form id="qualification-questionnaire"><div class="qualification-question-list">${model.factors.map(f=>`<div class="qualification-question"><label>${esc(f.question)}${f.required?' *':''}</label>${f.description?`<small>${esc(f.description)}</small>`:''}${qualificationQuestionControl(f)}<small>Weight ${Number(f.weight)}%</small></div>`).join('')}</div><div class="modal-actions"><button type="button" class="btn" id="qualification-cancel">Cancel</button><button class="btn btn-primary">Calculate new assessment</button></div></form><div id="qualification-result"></div>${assessments.length?`<details class="qualification-history" open><summary>Previous assessments (${assessments.length})</summary>${assessments.map(a=>`<div class="activity-row"><div><b>${esc(a.finalTemperature)} · score ${a.calculatedScore}</b><small>Calculated ${esc(a.calculatedTemperature)} · ${esc(a.modelName)} v${a.modelVersion} · ${fmtDate(a.assessedAt)}${a.overrideReason?` · Override reason: ${esc(a.overrideReason)}`:''}</small></div>${canOverride?`<button class="btn btn-sm" type="button" data-override-assessment="${a.id}">Override this result</button>`:''}</div>`).join('')}</details>`:''}</div>`);
  $('#qualification-cancel',o).addEventListener('click',()=>o.remove());
  $('#qualification-questionnaire',o).addEventListener('submit',async e=>{e.preventDefault();const inputs=Object.fromEntries(model.factors.map(f=>[f.code,e.target.elements[f.code].value]));try{const saved=await api(`/crm/leads/${lead.id}/qualification-assessments`,{method:'POST',body:{inputs}}),recommendation=saved.recommendation||{};$('#qualification-result',o).innerHTML=`<div class="qualification-result"><h3>${esc(saved.finalTemperature)} · score ${saved.calculatedScore}</h3><p>${esc(recommendation.strategy||'Qualification calculated from the active approved model.')}</p>${saved.contributions.map(x=>`<div><b>${esc(x.label)}</b><span>Answer ${x.value??'missing'} · weight ${x.weight}% · contribution ${Number(x.contribution||0).toFixed(2)}</span></div>`).join('')}</div>`;const value=$('#lead-qualification-value',parent);if(value)value.value=saved.finalTemperature;const badge=parent.querySelector('.lead-temp');if(badge){badge.textContent=saved.finalTemperature;badge.className=`lead-temp temp-${saved.finalTemperature.toLowerCase()}`;}toast('Qualification calculated and assessment history saved');loadCRMLeads();}catch(err){toast(err.message);}});
  o.querySelectorAll('[data-override-assessment]').forEach(b=>b.addEventListener('click',()=>{const source=assessments.find(x=>x.id===b.dataset.overrideAssessment),p=overlay(`<div class="modal" style="max-width:620px"><button class="close-x">×</button><h2>Override existing qualification</h2><p class="tool-note">The original answers and calculated score remain unchanged. This creates a separate audited override record.</p><div class="kv-grid"><div><b>Calculated result</b>${esc(source.calculatedTemperature)}</div><div><b>Current final result</b>${esc(source.finalTemperature)}</div><div><b>Score</b>${source.calculatedScore}</div></div><form id="qualification-override-form"><div class="form-grid"><div><label>Override result *</label><select name="overrideTemperature" required><option value="">Select result</option>${['Hot','Warm','Cold'].map(x=>`<option ${x===source.calculatedTemperature?'disabled':''}>${x}</option>`).join('')}</select></div><div class="span2"><label>Mandatory override reason *</label><input name="overrideReason" required></div></div><div class="modal-actions"><button class="btn btn-primary">Apply audited override</button></div></form></div>`);$('#qualification-override-form',p).addEventListener('submit',async e=>{e.preventDefault();try{const saved=await api(`/crm/leads/${lead.id}/qualification-assessments/${source.id}/override`,{method:'POST',body:Object.fromEntries(new FormData(e.target))});toast(`Qualification overridden to ${saved.finalTemperature}`);p.remove();o.remove();const value=$('#lead-qualification-value',parent);if(value)value.value=saved.finalTemperature;const badge=parent.querySelector('.lead-temp');if(badge){badge.textContent=saved.finalTemperature;badge.className=`lead-temp temp-${saved.finalTemperature.toLowerCase()}`;}loadCRMLeads();}catch(err){toast(err.message);}});}));
};

loadRoutingRules=async function(){try{const[{rules},{teams},{areas}]=await Promise.all([api('/admin/routing-rules'),api('/crm/teams'),api('/admin/areas')]);$('#routing-team').innerHTML='<option value="">Company Unassigned Queue</option>'+teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#routing-area').innerHTML='<option value="">All areas</option>'+areas.filter(a=>a.active).map(a=>`<option value="${a.id}">${esc(a.businessLabel)} · ${esc(a.emirate)}</option>`).join('');$('#inv-team').innerHTML=$('#add-user-team').innerHTML='<option value="">Not applicable</option>'+teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#routing-table').innerHTML=`<table><tr><th>Priority</th><th>Rule</th><th>Source / business</th><th>Area</th><th>Destination team queue</th><th>Status</th><th>Actions</th></tr>${rules.map(x=>`<tr><td>${x.priority}</td><td>${esc(x.name)}</td><td>${esc(x.source||'Any source')} · ${esc(x.businessType||'Any business')}</td><td>${esc(x.areaLabel||'All areas')}</td><td>${x.teamName?esc(x.teamName)+' · unassigned queue':'Company Unassigned Queue'}</td><td>${x.active?'Active':'Retired'}</td><td><button class="btn btn-sm" data-edit-routing="${x.id}" ${x.active?'':'disabled'}>Edit</button> <button class="btn btn-sm" data-toggle-routing="${x.id}" data-active="${x.active?0:1}">${x.active?'Retire':'Reactivate'}</button></td></tr>`).join('')}</table>`;$('#routing-table').querySelectorAll('[data-edit-routing]').forEach(button=>button.addEventListener('click',()=>editRoutingRule(rules.find(rule=>rule.id===button.dataset.editRouting))));$('#routing-table').querySelectorAll('[data-toggle-routing]').forEach(button=>button.addEventListener('click',async()=>{const active=button.dataset.active==='1',reason=prompt(`Reason for ${active?'reactivating':'retiring'} this routing rule`);if(!reason)return;try{await api(`/admin/routing-rules/${button.dataset.toggleRouting}`,{method:'PATCH',body:{active,reason}});toast(active?'Routing rule reactivated':'Routing rule retired');clearRoutingForm();loadRoutingRules();}catch(err){toast(err.message);}}));}catch(err){$('#routing-table').textContent=err.message;}};
